from fixtures import load_fixtures, ROWS
from digest import FixtureSummary

MEAN = sum(v for _, v in ROWS) / len(ROWS)


def test_mean_of_stored():
    assert abs(FixtureSummary(load_fixtures()).mean_goals() - MEAN) < 1e-9


def test_count_then_mean():
    s = FixtureSummary(load_fixtures())
    assert s.count() == len(ROWS) and abs(s.mean_goals() - MEAN) < 1e-9


def test_mean_twice():
    s = FixtureSummary(load_fixtures())
    s.mean_goals()
    assert abs(s.mean_goals() - MEAN) < 1e-9


def test_list_input():
    assert abs(FixtureSummary(list(load_fixtures())).mean_goals() - MEAN) < 1e-9


def test_empty():
    assert FixtureSummary(iter([])).mean_goals() == 0.0
